<?php
require_once __DIR__.'/auth.php';
require_once __DIR__.'/../report_activity.php';
require_once __DIR__.'/activity_filters.php';
$filter=activityFilterQuery($_GET);$filters=$filter['filters'];
if($_SESSION['role']==='staff'){
 if(($_GET['export']??'')==='csv'){http_response_code(403);exit('Only administrators can export activity reports.');}
 $filter['where'].=($filter['where']===''?' WHERE ':' AND ').'a.actor_id=?';$filter['params'][]=(int)$_SESSION['user_id'];
}
$join=' FROM complaint_activity a JOIN complaints c ON c.id=a.complaint_id';
if($filter['error'])http_response_code(422);
if(($_GET['export']??'')==='csv'){
 if($filter['error']){header('Content-Type: text/plain; charset=UTF-8');exit($filter['error']);}
 header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="resident-report-activity.csv"');header('Cache-Control: private, no-store');
 session_write_close();
 $pdo->setAttribute(PDO::MYSQL_ATTR_USE_BUFFERED_QUERY,false);
 $q=$pdo->prepare('SELECT a.id,a.created_at,a.actor_name,a.event_type,a.complaint_id,c.complainant_name,c.complaint_type,c.status,a.summary'.$join.$filter['where'].' ORDER BY a.created_at DESC,a.id DESC');$q->execute($filter['params']);
 $out=fopen('php://output','w');echo "\xEF\xBB\xBF";
 fputcsv($out,['Activity ID','Recorded at','Recorded by','Action','Report ID','Resident','Category','Current report status','Action details']);
 while($row=$q->fetch(PDO::FETCH_ASSOC)){
  $row['event_type']=$filter['types'][$row['event_type']]??$row['event_type'];
  foreach($row as &$cell){$cell=(string)$cell;if(preg_match('/^[\s]*[=+\-@]/u',$cell)||preg_match('/^[\t\r\n]/',$cell))$cell="'".$cell;}unset($cell);
  fputcsv($out,array_values($row));
 }
 fclose($out);exit;
}
$q=$pdo->prepare('SELECT COUNT(*),COUNT(DISTINCT a.complaint_id),COUNT(DISTINCT a.actor_id)'.$join.$filter['where']);$q->execute($filter['params']);[$total,$reportTotal,$actorTotal]=array_map('intval',$q->fetch(PDO::FETCH_NUM));
$page=max(1,(int)($_GET['page']??1));$pages=max(1,(int)ceil($total/50));$page=min($page,$pages);$offset=($page-1)*50;
$q=$pdo->prepare('SELECT a.*,c.complaint_type,c.complainant_name,c.status'.$join.$filter['where'].' ORDER BY a.created_at DESC,a.id DESC LIMIT 50 OFFSET '.$offset);$q->execute($filter['params']);$items=$q->fetchAll(PDO::FETCH_ASSOC);
$actors=$pdo->query('SELECT actor_id,MAX(actor_name) AS actor_name FROM complaint_activity WHERE actor_id IS NOT NULL'.($_SESSION['role']==='staff'?' AND actor_id='.(int)$_SESSION['user_id']:'').' GROUP BY actor_id ORDER BY actor_name')->fetchAll(PDO::FETCH_ASSOC);
$actorLabel='All recorded actors';foreach($actors as $actor)if((string)$actor['actor_id']===$filters['actor'])$actorLabel=$actor['actor_name'];
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Activity Logs — Barangay Mudiang</title><link rel="stylesheet" href="../assets/vendor/bootstrap.min.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"><?php include __DIR__.'/../ui_theme.php'; ?></head><body class="portal-page resident-directory">
<?php require_once __DIR__.'/../portal_navigation.php'; renderPortalNavigation(); ?>
<main class="main"><header class="topbar"><div class="topbar-left"><span class="portal-kicker">Community operations / Accountability</span><h1><?= $_SESSION['role']==='staff'?'My activity':'Activity logs' ?></h1><p>See who followed up, changed a report, or added a remark.</p></div><div class="topbar-right"><button type="button" class="btn btn-outline activity-print" onclick="window.print()"><i class="fas fa-print" aria-hidden="true"></i> Print page</button><?php if($_SESSION['role']==='admin'): ?><a class="btn btn-primary" href="?<?php echo reportActivityEscape(http_build_query($filters+['export'=>'csv'])); ?>"><i class="fas fa-file-csv" aria-hidden="true"></i> Export CSV</a><?php endif; ?></div></header><div class="content"><section class="dashboard-intro"><div><span class="portal-kicker">An accountable response</span><h2>Every action has a name.</h2><p>Staff messages and report updates are recorded with their author, report number, and time.</p></div><span class="intro-tag"><?php echo $total; ?> recorded actions</span></section><section class="card activity-filter-card no-print"><div class="card-header"><h2><i class="fas fa-filter" aria-hidden="true"></i> Find report activity</h2></div><div class="card-body"><form method="get" class="activity-filters"><div><label for="activity-search">Resident or report</label><input class="form-control" id="activity-search" name="q" maxlength="100" value="<?php echo reportActivityEscape($filters['q']); ?>" placeholder="Name, report #, category or details"></div><div><label for="activity-actor">Recorded by</label><select class="form-select" id="activity-actor" name="actor"><option value="">All recorded actors</option><?php foreach($actors as $actor): ?><option value="<?php echo (int)$actor['actor_id']; ?>" <?php echo $filters['actor']===(string)$actor['actor_id']?'selected':''; ?>><?php echo reportActivityEscape($actor['actor_name']); ?></option><?php endforeach; ?></select></div><div><label for="activity-type">Action</label><select class="form-select" id="activity-type" name="type"><option value="">All actions</option><?php foreach($filter['types'] as $value=>$label): ?><option value="<?php echo $value; ?>" <?php echo $filters['type']===$value?'selected':''; ?>><?php echo $label; ?></option><?php endforeach; ?></select></div><div><label for="activity-from">From</label><input class="form-control" id="activity-from" type="date" name="from" value="<?php echo reportActivityEscape($filters['from']); ?>"></div><div><label for="activity-to">To</label><input class="form-control" id="activity-to" type="date" name="to" value="<?php echo reportActivityEscape($filters['to']); ?>"></div><div class="activity-filter-actions"><button class="btn btn-primary" type="submit">Apply filters</button><a class="btn btn-outline" href="activity.php">Reset</a></div></form><?php if($filter['error']): ?><p class="alert alert-danger mt-3" role="alert"><?php echo reportActivityEscape($filter['error']); ?></p><?php endif; ?></div></section>
<div class="activity-summary"><span><strong><?php echo $total; ?></strong> matching actions</span><span><strong><?php echo $reportTotal; ?></strong> resident reports</span><span><strong><?php echo $actorTotal; ?></strong> recorded actors</span></div>
<p class="activity-print-context">Resident report accountability · <?php echo reportActivityEscape($filters['from']?:'All dates'); ?> to <?php echo reportActivityEscape($filters['to']?:'present'); ?> · Search: <?php echo reportActivityEscape($filters['q']?:'All reports'); ?> · Action: <?php echo reportActivityEscape($filter['types'][$filters['type']]??'All actions'); ?> · Recorded by: <?php echo reportActivityEscape($actorLabel); ?> · Page <?php echo $page; ?> of <?php echo $pages; ?> · Use CSV export for all matching records.</p><section class="card"><div class="card-header"><h2><i class="fas fa-history" aria-hidden="true"></i> Resident report accountability</h2></div><div class="report-activity-list"><?php foreach($items as $item): ?><article class="report-activity-item"><span class="activity-dot" aria-hidden="true"></span><div><strong><?php echo reportActivityEscape($item['actor_name']); ?></strong><span class="activity-kind"><?php echo reportActivityEscape($filter['types'][$item['event_type']]??ucfirst($item['event_type'])); ?></span><p><?php echo nl2br(reportActivityEscape($item['summary'])); ?></p><a href="edit_complaint.php?id=<?php echo (int)$item['complaint_id']; ?>#report-activity">Report #<?php echo (int)$item['complaint_id']; ?> · <?php echo reportActivityEscape($item['complaint_type']); ?></a><div class="activity-resident-context"><span><i class="fas fa-user" aria-hidden="true"></i> <?php echo reportActivityEscape($item['complainant_name']); ?></span><span>Current status: <?php echo reportActivityEscape(ucfirst($item['status'])); ?></span><span>Log #<?php echo (int)$item['id']; ?></span></div><time><?php echo reportActivityEscape($item['created_at']); ?></time></div></article><?php endforeach; ?><?php if(!$items): ?><p class="activity-empty">No activity matches these filters. Try another resident, report, or date range.</p><?php endif; ?></div><nav class="directory-pagination" aria-label="Activity pages"><?php if($page>1): ?><a href="?<?php echo reportActivityEscape(http_build_query($filters+['page'=>$page-1])); ?>">Previous</a><?php endif; ?><span>Page <?php echo $page; ?> of <?php echo $pages; ?></span><?php if($page<$pages): ?><a href="?<?php echo reportActivityEscape(http_build_query($filters+['page'=>$page+1])); ?>">Next</a><?php endif; ?><a class="nav-item" href="../account.php"><i class="fas fa-lock" aria-hidden="true"></i> Account security</a></nav></section></div></main><?php include __DIR__.'/notification_widget.php'; ?></body></html>
